/* Bovitech Super App — v2.47: stock and ordering, from the ezyVet walkthrough.
   • 📥 Receive a delivery: against a purchase order or with none — the supplier's invoice attached (drag and drop), how much came,
     batch and expiry. Stock only goes up on what's received. Cost price changes show old → new: a price rise is ticked to update,
     a drop isn't (it may be a one-off special). Anything with less than 6 months to expiry is flagged (Settings → Clinical records).
   • ⚠️ Order problems: broken / short / wrong / short-dated / other, with comments. The delivery stays a problem to sort out until it's
     resolved — the problem items only go into stock when you say so (or a replacement is coming, or it's credited).
   • 💲 Supplier price breaks: quantity tiers per item and supplier; orders use the tier's price and suggest the better quantity.
   • 🗑️ Write-offs: expired, broken, wasted (the list is editable) — who, why, which item, how much and the batch, kept in the history.
   • 📋 Yearly stocktake (admin): expected quantities, type the counts, review the differences, confirm — CSV and PDF.
   • 💰 Stock value (admin): quantity × cost by category and item, with a total — CSV and PDF.
   • Suggested mark-up bands (Settings → Clinical records) — a guide on the price list item, one tap to use it.
   • 💲 Pricing check: anything sold below cost, a negative price, or below cost once a discount rule applies. */
['stkrcv', 'stktake'].forEach((k) => { if (typeof BOOK_KINDS !== 'undefined' && !BOOK_KINDS.includes(k)) BOOK_KINDS.push(k); }); // synced with everything else
const U10 = { files: [], rcv: null };
const u10S = () => D.settings || (D.settings = {});
const u10Months = () => (+u10S().stkExpMonths > 0 ? +u10S().stkExpMonths : 6);
const U10_REASONS = ['Expired', 'Broken', 'Wasted'];
const u10Reasons = () => { const L = u10S().adjReasons; return Array.isArray(L) && L.length ? L : U10_REASONS; };
const U10_PROBS = [['', 'No problem'], ['broken', 'Broken'], ['short', 'Short (fewer came)'], ['wrong', 'Wrong item'], ['dated', 'Short-dated'], ['other', 'Something else']];
const u10ProbName = (k) => (U10_PROBS.find((x) => x[0] === k) || [k, k])[1];
const u10Me = () => (window.SBAuth && SBAuth.staff && SBAuth.staff.id) || null;
const u10Who = (id) => (id && typeof Bk !== 'undefined' && Bk.pname ? Bk.pname(id) : '') || '';
const u10Date = (t) => new Date(t).toLocaleString('en-AU', { day: 'numeric', month: 'short', year: 'numeric', hour: 'numeric', minute: '2-digit' });
const u10Esc = (v) => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
function u10Csv(name, rows) { const blob = new Blob(['﻿' + rows.map((r) => r.map(u10Esc).join(',')).join('\r\n')], { type: 'text/csv' }); const u = URL.createObjectURL(blob); const l = document.createElement('a'); l.href = u; l.download = name; document.body.appendChild(l); l.click(); l.remove(); setTimeout(() => URL.revokeObjectURL(u), 4000); }
function u10Print(title, html) { const w = window.open('', '_blank'); if (!w) { toast('Allow pop-ups to print or save as PDF', 'warn'); return; } w.document.write(`<html><head><title>${h(title)}</title><style>body{font-family:system-ui,sans-serif;padding:20px;font-size:13px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:4px 6px;text-align:left}td.n,th.n{text-align:right}h1{font-size:20px}h2{font-size:16px;margin-top:18px}</style></head><body><h1>${h(title)}</h1><div>Bovitech Veterinary Services · ${new Date().toLocaleDateString('en-AU')}</div>${html}</body></html>`); w.document.close(); setTimeout(() => w.print(), 300); }
const u10Months2 = (exp) => { if (!exp) return null; const d = new Date(exp + 'T12:00'); const n = new Date(); return (d - n) / (30.44 * 864e5); };
const u10ShortDated = (exp) => { const m = u10Months2(exp); return m != null && m < u10Months(); };
const u10Cat = (p) => (typeof stk2Cat === 'function' ? stk2Cat(p) : '');
const u10CatName = (id) => (typeof stk2CatName === 'function' ? stk2CatName(id) : id) || 'Other';
const u10Sale = (p) => (typeof stk2Sale === 'function' ? stk2Sale(p) : +p.price || 0);
const u10Sups = (p) => (typeof stk2Sups === 'function' ? stk2Sups(p) : []);

/* ---------- suggested mark-up bands ---------- */
const U10_BANDS = { s4: [[0, 10, 200], [10, 20, 110], [20, 30, 100], [30, 100, 90], [100, 200, 50], [200, '', 30]], consumable: [[0, 10, 200], [10, '', 50]], otc: [[0, '', 25]] };
const u10Bands = () => { const b = u10S().mkBands; return b && typeof b === 'object' && Object.keys(b).length ? b : U10_BANDS; };
function u10Suggest(cat, cost) { const B = u10Bands()[cat]; if (!B || !(cost > 0)) return null; const r = B.slice().sort((a, b) => (+a[0] || 0) - (+b[0] || 0)).find(([f, t]) => cost >= (+f || 0) && (t === '' || t == null || cost < +t)); return r ? +r[2] : null; }
function u10SugTxt() { const sh = document.getElementById('sheet'); if (!sh) return; const w = document.getElementById('stk2-mkw'); if (!w) return; let el = document.getElementById('u10-sug'); if (!el) { el = document.createElement('div'); el.id = 'u10-sug'; el.className = 'hint'; el.style.margin = '-2px 0 8px'; const s = document.getElementById('stk2-sale'); if (s) s.parentNode.insertBefore(el, s.nextSibling); else w.parentNode.appendChild(el); }
  const cat = (document.getElementById('stk2-cat') || {}).value; const unit = +((document.getElementById('stk2-cost') || {}).value) || 0; const pack = +((document.getElementById('cp-pack') || {}).value) || 0; const cost = pack > 1 ? unit * pack : unit; const pct = u10Suggest(cat, cost);
  el.innerHTML = pct == null ? '' : `💡 Suggested mark-up: <b>${pct}%</b> <span class="hint">(${h(u10CatName(cat))}, cost ${crMoney(cost)}${pack > 1 ? ' a ' + h((document.getElementById('cp-packname') || {}).value || 'bottle') : ''} — a guide only)</span> <button type="button" class="btn small" data-act="u10-usemk" data-v="${pct}">Use ${pct}%</button>`; }
document.addEventListener('click', (e) => { const el = e.target.closest && e.target.closest('[data-act=u10-usemk]'); if (!el) return; e.preventDefault(); e.stopPropagation(); const r = document.querySelector('#sheet [name=stk2-by][value=markup]'); if (r) r.checked = true; const m = document.getElementById('stk2-mk'); if (m) m.value = el.dataset.v; if (typeof stk2SaleTxt === 'function') stk2SaleTxt(); u10SugTxt(); }, true);
document.addEventListener('input', (e) => { if (e.target.closest && e.target.closest('#sheet') && /^(stk2-cost|cp-pack)$/.test(e.target.id)) u10SugTxt(); });
document.addEventListener('change', (e) => { if (e.target.closest && e.target.closest('#sheet') && /^(stk2-cat|cp-pack)$/.test(e.target.id)) u10SugTxt(); });
if (typeof crProdOpen === 'function') crProdOpen = (function (orig) { return function () { const r = orig.apply(this, arguments); setTimeout(u10SugTxt, 0); return r; }; })(crProdOpen);

/* ---------- 💲 pricing check ---------- */
function u10PriceIssues() { const out = []; crList('crprod').filter((p) => !p.gone && p.active !== false).forEach((p) => { const sale = u10Sale(p); const cost = +p.cost || 0; const why = [];
  if (+p.price < 0 || sale < 0 || +p.pricePack < 0) why.push('it has a negative price');
  if (cost > 0 && sale > 0 && sale < cost - 1e-6) why.push(`it sells for ${crMoney(sale)} — below its cost of ${crMoney(cost)}`);
  if (cost > 0 && +p.pack > 1 && +p.pricePack > 0 && +p.pricePack < cost * p.pack - 1e-6) why.push(`a whole ${h(p.packName || 'bottle')} sells for ${crMoney(p.pricePack)} — below its cost of ${crMoney(cost * p.pack)}`);
  if (cost > 0 && sale > 0 && Array.isArray(p.disc) && p.disc.length && typeof discBest === 'function') { const b = discBest(p.disc, 1e9, sale); if (b && b.p < sale && b.p < cost - 1e-6) why.push(`with the "${b.r.label || 'discount'}" rule it's ${crMoney(b.p)} — below cost`); }
  if (!why.length) return; const key = why.join('|'); if (p.priceOk === key) return; out.push({ p, why, key }); }); return out; }

/* ---------- 💲 supplier price breaks ---------- */
const u10Breaks = (p, sup) => (Array.isArray(p.breaks) ? p.breaks : []).filter((b) => b && +b.qty > 0 && +b.price >= 0 && (!b.sup || !sup || String(b.sup).toLowerCase() === String(sup).toLowerCase())).sort((a, b) => a.qty - b.qty);
function u10Tier(p, sup, qty) { let best = null; u10Breaks(p, sup).forEach((b) => { if (qty >= +b.qty && (!best || +b.price < +best.price)) best = b; }); return best; }
function u10NextTier(p, sup, qty, cur) { return u10Breaks(p, sup).find((b) => +b.qty > qty && +b.price < cur) || null; }
function u10BreaksSheet(pid) { const p = crProd(pid); if (!p) return; const sups = u10Sups(p).map((s) => (s.bid && IDX.biz.get(s.bid) ? IDX.biz.get(s.bid).name : s.name)).filter(Boolean); const main = (u10Sups(p).find((s) => s.main) || {}); const mainName = main.bid && IDX.biz.get(main.bid) ? IDX.biz.get(main.bid).name : main.name || '';
  const row = (b) => `<div class="u10-brow" style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin:4px 0"><select class="u10-bs" aria-label="Supplier"><option value="">Any supplier</option>${[...new Set([...sups, ...(b.sup ? [b.sup] : [])])].map((s) => `<option ${String(s) === String(b.sup || '') ? 'selected' : ''}>${h(s)}</option>`).join('')}</select><label class="hint">From</label><input class="u10-bq" type="number" min="1" step="any" value="${b.qty || ''}" style="width:80px" aria-label="From this quantity"><label class="hint">cost each $</label><input class="u10-bp" type="number" min="0" step="0.0001" value="${b.price ?? ''}" style="width:100px" aria-label="Cost each ex GST"><button type="button" class="btn small" data-act="u10-bdel" aria-label="Delete this price break">🗑️</button></div>`;
  openSheet('💲 Price breaks — ' + p.name, `<div class="hint" style="margin-bottom:6px">The cost price from the supplier when you buy at least this many (ex GST, per ${h(p.unit && p.unit !== 'each' ? p.unit : 'item')} as you order it). Orders use the cheapest break you reach, and suggest the next one. These are what we pay — client discounts are separate (🏷️ Discount rules).</div><div id="u10-brows">${u10Breaks(p).map(row).join('')}</div><template id="u10-btpl">${row({ sup: mainName })}</template><button type="button" class="btn small" data-act="u10-badd">➕ Add a price break</button>`, async () => {
    const L = [...document.querySelectorAll('#u10-brows .u10-brow')].map((r) => ({ sup: r.querySelector('.u10-bs').value, qty: +r.querySelector('.u10-bq').value || 0, price: r.querySelector('.u10-bp').value === '' ? null : +r.querySelector('.u10-bp').value })).filter((b) => b.qty > 0 && b.price != null).sort((a, b) => a.qty - b.qty);
    if (!(await ask(`Save ${L.length} price break${L.length === 1 ? '' : 's'} for ${p.name}?`, 'Yes — save'))) return false; p.breaks = L; touch(p); stkSync(); setTimeout(renderAll, 0); toast('Saved'); return true; });
  if (!u10Breaks(p).length) document.querySelector('[data-act=u10-badd]').click(); if (SHEET) SHEET.snap = sheetState(); }
document.addEventListener('click', (e) => { const el = e.target.closest && e.target.closest('[data-act=u10-badd],[data-act=u10-bdel]'); if (!el) return; e.preventDefault(); e.stopPropagation(); if (el.dataset.act === 'u10-bdel') el.closest('.u10-brow').remove(); else { const tp = document.getElementById('u10-btpl'); if (tp) document.getElementById('u10-brows').insertAdjacentHTML('beforeend', tp.innerHTML); } }, true);
/* orders use the tier price for the quantity */
function u10ApplyTier(o, l) { const p = crProd(l.prod); if (!p || !u10Breaks(p, o.supName).length) return; const t = u10Tier(p, o.supName, +l.qty || 0); const base = p.supPrice || p.cost || 0; const np = t ? +t.price : base; if (np !== +l.price) { l.price = np; l.tier = t ? +t.qty : null; touch(o); } }
if (typeof stkPoAddProd === 'function') stkPoAddProd = (function (orig) { return function (o, p) { const r = orig.apply(this, arguments); const l = (o.lines || []).find((x) => x.prod === p.id && !x.cancel); if (l) u10ApplyTier(o, l); return r; }; })(stkPoAddProd);
document.addEventListener('change', (e) => { const el = e.target; if (!el.classList || !el.classList.contains('stk-poq')) return; const o = stkL('stkpo').find((x) => x.id === el.dataset.po); const l = o && o.lines[+el.dataset.i]; if (!l) return; const before = l.price; u10ApplyTier(o, l); if (before !== l.price) { stkSync(); renderAll(); } });
function u10PoBreaksHtml(o) { if (o.status !== 'draft') return ''; const S2 = (o.lines || []).filter((l) => !l.cancel).map((l, i) => { const p = crProd(l.prod); if (!p) return null; const n = u10NextTier(p, o.supName, +l.qty || 0, +l.price || 0); const t = u10Tier(p, o.supName, +l.qty || 0); if (!n && !t) return null; return { p, l, i: o.lines.indexOf(l), n, t }; }).filter(Boolean); if (!S2.length) return '';
  return `<div class="card u10-pobreaks"><h3>💲 Price breaks on this order</h3>${S2.map((x) => `<div class="kv" style="align-items:center;flex-wrap:wrap"><div class="v" style="flex:1"><b>${h(x.p.name)}</b> × ${x.l.qty} at ${crMoney(x.l.price)} each${x.t ? ` <span class="hint">(the ${x.t.qty}+ price)</span>` : ''}${x.n ? `<br><span class="hint">Buy <b>${x.n.qty}</b> and it's ${crMoney(x.n.price)} each — ${crMoney(x.n.qty * x.n.price)} for ${x.n.qty} (now ${crMoney(x.l.qty * x.l.price)} for ${x.l.qty})</span>` : ''}</div>${x.n ? `<button class="btn small" data-act="u10-usetier" data-po="${o.id}" data-i="${x.i}" data-q="${x.n.qty}">Make it ${x.n.qty}</button>` : ''}</div>`).join('')}</div>`; }
document.addEventListener('click', (e) => { const el = e.target.closest && e.target.closest('[data-act=u10-usetier]'); if (!el) return; e.preventDefault(); e.stopPropagation(); const o = stkL('stkpo').find((x) => x.id === el.dataset.po); const l = o && o.lines[+el.dataset.i]; if (!l) return; l.qty = +el.dataset.q; u10ApplyTier(o, l); touch(o); stkSync(); renderAll(); toast(`Changed to ${l.qty} at ${crMoney(l.price)} each`); }, true);

/* ---------- 📥 receiving a delivery (with or without an order) ---------- */
const u10Rcvs = () => stkL('stkrcv').filter((r) => !r.gone);
const u10OpenIssues = () => u10Rcvs().filter((r) => r.issue === 'open');
function u10PoStatus(o) { if (!o) return; if (u10Rcvs().some((r) => r.po === o.id && r.issue === 'open')) o.status = 'issue'; else if (o.status === 'issue' || o.status === 'part' || o.status === 'sent' || o.status === 'done') o.status = (o.lines || []).every((l) => stkLineLeft(l) <= 0) ? 'done' : (o.lines || []).some((l) => +l.got > 0) ? 'part' : 'sent'; touch(o); }
const u10Base = (p) => (p ? +(p.supPrice || p.cost || 0) : 0);
function u10LineRow(x, i) { const p = crProd(x.prod); const unit = p && p.unit && p.unit !== 'each' ? p.unit : ''; const old = x.oldPrice;
  return `<div class="card u10-rl" data-i="${i}" data-prod="${h(x.prod)}" style="padding:8px;margin:6px 0"><div class="kv" style="align-items:center"><div class="v"><b>${h(p ? p.name : x.name || '?')}</b>${x.ordered != null ? ` <span class="hint">ordered ${x.ordered}${x.got ? ', ' + x.got + ' already in' : ''}</span>` : ''}${x.per > 1 ? ` <span class="hint">(${x.per} ${h(unit)} each)</span>` : ''}</div>${x.ordered == null ? `<button type="button" class="btn small" data-act="u10-rldel" aria-label="Remove this item">🗑️</button>` : ''}</div>
    <div class="grid2"><div class="f"><label>How many came</label><input class="u10-q" type="number" min="0" step="any" value="${x.qty ?? ''}"></div><div class="f"><label>Cost each on the invoice (ex GST, $)</label><input class="u10-pr" type="number" min="0" step="0.0001" value="${x.price ?? ''}"></div>
      <div class="f"><label>Batch</label><input class="u10-b" value="${h(x.batch || '')}"></div><div class="f"><label>Expiry</label><input class="u10-x" type="date" value="${h(x.exp || '')}"></div></div>
    <div class="u10-cost hint" data-old="${old ?? ''}"></div><div class="u10-exp"></div>
    ${x.ordered != null ? `<div class="grid2 u10-rest" hidden><div class="f"><label>The rest that didn't come is…</label><select class="u10-rs"><option value="bo">On backorder</option><option value="cancel">Not coming — cancelled</option></select></div><div class="f"><label>Backorder expected</label><input class="u10-re" type="date"></div></div>` : ''}
    <div class="grid2"><div class="f"><label>Any problem?</label><select class="u10-pb">${U10_PROBS.map(([k, l]) => `<option value="${k}">${h(l)}</option>`).join('')}</select></div><div class="f u10-pbw" hidden><label>How many have the problem</label><input class="u10-pq" type="number" min="0" step="any"></div></div>
    <div class="f u10-pbw" hidden><label>What's wrong</label><textarea class="u10-pn" rows="2"></textarea></div></div>`; }
function u10LineLive(row) { const p = crProd(row.dataset.prod); const q = +row.querySelector('.u10-q').value || 0; const pr = row.querySelector('.u10-pr').value; const cbox = row.querySelector('.u10-cost'); const old = cbox.dataset.old === '' ? null : +cbox.dataset.old;
  if (pr !== '' && old != null && Math.abs(+pr - old) > 1e-6) { const up = +pr > old; const was = cbox.querySelector('.u10-up'); const keep = was ? was.dataset.touched === '1' ? was.checked : up : up; cbox.innerHTML = `${up ? '▲' : '▼'} Cost was <b>${crMoney(old)}</b>, now <b>${crMoney(+pr)}</b> (${up ? '+' : ''}${crR2((+pr / (old || 1) - 1) * 100)}%) <label class="bk-radio" style="display:inline-flex;margin-left:6px"><input type="checkbox" class="u10-up" ${keep ? 'checked' : ''} data-touched="${was ? was.dataset.touched || '' : ''}"> Update the cost price${p && p.priceBy === 'markup' ? ' (the sale price follows its mark-up)' : ''}</label>${up ? '' : ' <span class="hint">— not ticked: it may be a one-off special</span>'}`; } else cbox.innerHTML = '';
  const x = row.querySelector('.u10-x').value; const eb = row.querySelector('.u10-exp'); eb.innerHTML = x && u10ShortDated(x) ? `<div class="bk-warnbox">⚠ Only ${Math.max(0, Math.floor(u10Months2(x)))} month${Math.floor(u10Months2(x)) === 1 ? '' : 's'} to expiry — less than the ${u10Months()} months we ask suppliers for. Set "Any problem?" to Short-dated if it's going back.</div>` : '';
  const pb = row.querySelector('.u10-pb').value; row.querySelectorAll('.u10-pbw').forEach((w) => { w.hidden = !pb; }); const pq = row.querySelector('.u10-pq'); if (pb && pq.value === '') pq.value = q || '';
  const rest = row.querySelector('.u10-rest'); if (rest) { const left = +row.dataset.left || 0; rest.hidden = !(q < left); } }
document.addEventListener('input', (e) => { const row = e.target.closest && e.target.closest('.u10-rl'); if (row) u10LineLive(row); });
document.addEventListener('change', (e) => { const row = e.target.closest && e.target.closest('.u10-rl'); if (!row) return; if (e.target.classList.contains('u10-up')) e.target.dataset.touched = '1'; u10LineLive(row); });
function u10FileZone() { return `<div class="f"><label>📎 The supplier's invoice</label><div class="att-zone u10-zone" style="border:2px dashed var(--line,#ccc);border-radius:10px;padding:12px;text-align:center"><div id="u10-flist" class="hint">Drag the invoice here, or</div><label class="btn small" style="margin-top:6px">Choose a file<input type="file" id="u10-file" multiple hidden></label></div></div>`; }
function u10FilesShow() { const el = document.getElementById('u10-flist'); if (!el) return; el.innerHTML = U10.files.length ? U10.files.map((f, i) => `<div>📎 ${h(f.name)} <span class="hint">${typeof attKb === 'function' ? attKb(f.size) : ''}</span> <button type="button" class="btn small" data-act="u10-fdel" data-i="${i}" aria-label="Remove this file">🗑️</button></div>`).join('') : 'Drag the invoice here, or'; }
function u10AddFiles(list) { for (const f of list) { if (typeof ATT_MAX !== 'undefined' && f.size > ATT_MAX) { toast(`${f.name} is too big — the limit is ${attKb(ATT_MAX)}`, 'warn'); continue; } U10.files.push(f); } u10FilesShow(); }
document.addEventListener('change', (e) => { if (e.target.id === 'u10-file') { u10AddFiles([...e.target.files]); e.target.value = ''; } });
document.addEventListener('dragover', (e) => { const z = e.target.closest && e.target.closest('.u10-zone'); if (z) { e.preventDefault(); z.style.background = 'rgba(0,0,0,.04)'; } });
document.addEventListener('dragleave', (e) => { const z = e.target.closest && e.target.closest('.u10-zone'); if (z) z.style.background = ''; });
document.addEventListener('drop', (e) => { const z = e.target.closest && e.target.closest('.u10-zone'); if (!z) return; e.preventDefault(); e.stopPropagation(); z.style.background = ''; u10AddFiles([...(e.dataTransfer && e.dataTransfer.files || [])]); }, true);
document.addEventListener('click', async (e) => { const el = e.target.closest && e.target.closest('[data-act=u10-fdel],[data-act=u10-rldel],[data-act=u10-rladd]'); if (!el) return; e.preventDefault(); e.stopPropagation();
  if (el.dataset.act === 'u10-fdel') { U10.files.splice(+el.dataset.i, 1); u10FilesShow(); return; }
  if (el.dataset.act === 'u10-rldel') { el.closest('.u10-rl').remove(); return; }
  const inp = document.getElementById('u10-add'); const nmq = ((inp || {}).value || '').trim().toLowerCase(); if (!nmq) { toast('Type or choose the item first'); if (inp) inp.focus(); return; } const p = crList('crprod').find((x) => !x.gone && (x.name || '').toLowerCase() === nmq) || crList('crprod').find((x) => !x.gone && ['med', 'consumable', 'merch'].includes(x.cat) && ((x.name || '') + ' ' + (x.code || '') + ' ' + (x.barcode || '')).toLowerCase().includes(nmq)); if (!p) { toast('No item matches "' + inp.value + '" in the price list', 'warn'); return; } inp.value = ''; const id = p.id; const box = document.getElementById('u10-lines'); if (!box) return; const i = box.querySelectorAll('.u10-rl').length; box.insertAdjacentHTML('beforeend', u10LineRow({ prod: id, qty: '', price: u10Base(p) || '', oldPrice: u10Base(p) || null, per: 1 }, i)); u10LineLive(box.lastElementChild); }, true);
async function u10Receive(o) { U10.files = []; const sup = o && o.sup && IDX.biz.get(o.sup);
  const lines = o ? o.lines.map((l, i) => ({ l, i })).filter((x) => stkLineLeft(x.l) > 0).map(({ l, i }) => { const p = crProd(l.prod); return { poi: i, prod: l.prod, ordered: l.qty, got: +l.got || 0, left: stkLineLeft(l), qty: stkLineLeft(l), per: l.per || 1, price: l.price ?? u10Base(p), tier: l.tier || null, oldPrice: l.tier && l.price != null ? +l.price : u10Base(p) || (l.price != null ? +l.price : null) }; }) : [];
  const supOpts = D.businesses.filter((b) => !b.gone && !(typeof isClientBiz === 'function' && isClientBiz(b))).map((b) => `<option value="${h(b.name)}">`).join('');
  openSheet(o ? `📥 Receive ${o.num} — ${o.supName || ''}` : '📥 Receive a delivery', `<div class="hint" style="margin-bottom:6px">Everything that's received goes into the office. Stock only goes up on what's received — not on what was ordered. Problem items are held back until they're sorted out.</div>
    ${o ? '' : `<div class="f"><label for="u10-sup">Supplier</label><input id="u10-sup" list="u10-supl" autocomplete="off"><datalist id="u10-supl">${supOpts}</datalist></div>`}
    <div class="f"><label for="u10-inv">Supplier's invoice number</label><input id="u10-inv"></div>${u10FileZone()}
    <div id="u10-lines">${lines.map((x, i) => u10LineRow(x, i)).join('')}</div>${o ? '' : `<div class="f"><label for="u10-add">Add an item</label><div style="display:flex;gap:6px"><input id="u10-add" list="u10-pl" autocomplete="off" style="flex:1"><button type="button" class="btn small" data-act="u10-rladd">➕ Add</button></div><datalist id="u10-pl">${crList('crprod').filter((x) => !x.gone && x.active !== false && ['med', 'consumable', 'merch'].includes(x.cat)).map((x) => `<option value="${h(x.name)}">`).join('')}</datalist></div>`}`, async () => u10RcvSave(o, lines));
  document.querySelectorAll('#u10-lines .u10-rl').forEach((row, i) => { if (lines[i]) row.dataset.left = lines[i].left; u10LineLive(row); }); if (SHEET) SHEET.snap = sheetState(); }
async function u10RcvSave(o, lines) { const rows = [...document.querySelectorAll('#u10-lines .u10-rl')]; const supName = o ? o.supName : ((document.getElementById('u10-sup') || {}).value || '').trim(); const invNo = ((document.getElementById('u10-inv') || {}).value || '').trim();
  const L = rows.map((row) => { const i = +row.dataset.i; const base = lines[i] && lines[i].prod === row.dataset.prod ? lines[i] : { prod: row.dataset.prod, per: 1 }; const q = +row.querySelector('.u10-q').value || 0; const pb = row.querySelector('.u10-pb').value; const bad = pb ? Math.min(q || +row.querySelector('.u10-pq').value || 0, +row.querySelector('.u10-pq').value || 0) : 0; const prv = row.querySelector('.u10-pr').value; const up = row.querySelector('.u10-up');
    return { ...base, qty: q, bad: pb ? Math.max(0, bad) : 0, prob: pb, note: (row.querySelector('.u10-pn') || {}).value || '', batch: row.querySelector('.u10-b').value.trim(), exp: row.querySelector('.u10-x').value, price: prv === '' ? null : +prv, upd: !!(up && up.checked), rest: (row.querySelector('.u10-rs') || {}).value || 'bo', restExp: (row.querySelector('.u10-re') || {}).value || '' }; }).filter((x) => x.qty > 0 || x.prob);
  if (!L.length) { toast('Type how many came'); return false; } if (!o && !supName) { toast('Type the supplier'); return false; }
  const nm = (x) => (crProd(x.prod) || {}).name || '?'; const good = L.filter((x) => x.qty - x.bad > 0); const bad = L.filter((x) => x.prob); const upd = L.filter((x) => x.upd && x.price != null); const dated = L.filter((x) => x.exp && u10ShortDated(x.exp) && x.prob !== 'dated');
  const ok = await askBox(o ? `📥 Receive ${o.num}?` : '📥 Receive this delivery?', `${good.length ? `<p><b>Into stock (office):</b><br>${good.map((x) => `• ${h(nm(x))} × ${crR4(x.qty - x.bad)}`).join('<br>')}</p>` : ''}${bad.length ? `<p><b>⚠️ Held back — problems to sort out:</b><br>${bad.map((x) => `• ${h(nm(x))} × ${x.bad} — ${h(u10ProbName(x.prob))}`).join('<br>')}</p>` : ''}${upd.length ? `<p><b>Cost prices to update:</b><br>${upd.map((x) => `• ${h(nm(x))}: ${crMoney(x.oldPrice)} → ${crMoney(x.price)}`).join('<br>')}</p>` : ''}${dated.length ? `<div class="bk-warnbox">⚠ Less than ${u10Months()} months to expiry: ${dated.map((x) => h(nm(x))).join(', ')} — going into stock anyway.</div>` : ''}${U10.files.length ? `<p>📎 ${U10.files.length} file${U10.files.length === 1 ? '' : 's'} attached.</p>` : '<p class="hint">No supplier invoice attached.</p>'}`, 'Yes — receive it'); if (!ok) return false;
  const sb = o ? o.sup && IDX.biz.get(o.sup) : D.businesses.find((b) => !b.gone && (b.name || '').toLowerCase() === supName.toLowerCase());
  const rc = { id: uid('rc'), at: Date.now(), by: u10Me(), po: o ? o.id : null, poNum: o ? o.num : '', sup: sb ? sb.id : null, supName: o ? o.supName : supName, invNo, lines: [], issue: bad.length ? 'open' : null, comments: [] };
  const why = 'Received — ' + (o ? o.num : invNo ? 'invoice ' + invNo : supName || 'delivery');
  L.forEach((x) => { const p = crProd(x.prod); const per = x.per || 1; const g = crR4(x.qty - x.bad); if (g > 0) stkAdd(x.prod, g * per, 'office', x.batch, x.exp, why, rc.id);
    if (o && x.poi != null) { const l = o.lines[x.poi]; if (l && l.prod === x.prod) { l.got = crR4((+l.got || 0) + x.qty); if (stkLineLeft(l) > 0) { if (x.rest === 'cancel') l.cancel = true; else l.bo = { exp: x.restExp || (l.bo && l.bo.exp) || '', at: Date.now() }; } else delete l.bo; } }
    if (x.upd && x.price != null && p) { const br = x.tier && (p.breaks || []).find((b) => +b.qty === +x.tier && (!b.sup || String(b.sup).toLowerCase() === String(rc.supName || '').toLowerCase())); if (br) { br.price = x.price; p.costLog = [...(p.costLog || []), { at: Date.now(), by: u10Me(), from: x.oldPrice, to: x.price, ref: rc.id, tier: x.tier }].slice(-30); touch(p); } else u10CostUpdate(p, x.oldPrice, x.price, rc.id); }
    rc.lines.push({ prod: x.prod, qty: x.qty, per, bad: x.bad, prob: x.prob || '', note: x.note || '', batch: x.batch, exp: x.exp, price: x.price, oldPrice: x.oldPrice ?? null, poi: x.poi ?? null, res: x.prob ? '' : null });
    if (x.prob && x.note) rc.comments.push({ at: Date.now(), by: u10Me(), t: `${nm(x)} — ${u10ProbName(x.prob)}: ${x.note}` }); });
  touch(rc); stkL('stkrcv').push(rc);
  for (const f of U10.files) { const a = { id: uid('att'), rec: 'stk:' + rc.id, bid: rc.sup, sec: 'stk', ref: null, name: f.name, type: f.type || 'application/octet-stream', size: f.size, b64: await attRead(f), at: Date.now(), by: typeof crMe === 'function' ? crMe() : u10Me() }; touch(a); crList('cratt').push(a); } U10.files = [];
  if (o) { o.recvAt = Date.now(); if (o.status === 'draft') o.status = 'sent'; u10PoStatus(o); }
  stkSync(); setTimeout(renderAll, 0); toast(bad.length ? '📥 Received — ⚠️ problems held back to sort out' : o && o.status === 'done' ? '✓ All received' : '📥 Received'); return true; }
function u10CostUpdate(p, oldP, newP, ref) { const ratio = +oldP > 0 ? newP / +oldP : null; const was = { cost: p.cost, supPrice: p.supPrice, price: p.price };
  if (p.supPrice != null && p.supPrice !== '') { p.supPrice = newP; if (Array.isArray(p.sups)) { const m = p.sups.find((s) => s.main) || p.sups[0]; if (m) m.price = newP; } if (+p.cost > 0 && ratio) p.cost = crR4(p.cost * ratio); else if (!+p.cost) p.cost = newP; } else p.cost = newP;
  if (p.priceBy === 'markup' && +p.cost && p.markup != null && p.markup !== '') { p.price = u10Sale(p); if (+p.pricePack > 0 && ratio) p.pricePack = crR2(p.pricePack * ratio); }
  p.costLog = [...(p.costLog || []), { at: Date.now(), by: u10Me(), from: oldP, to: newP, ref, was }].slice(-30); touch(p); }
if (typeof stkReceive === 'function') stkReceive = async function (o) { return u10Receive(o); };

/* ---------- ⚠️ sorting out an order problem ---------- */
const U10_RES = [['', 'Still sorting it out'], ['keep', 'Keep it — put it into stock'], ['repl', 'A replacement is coming'], ['credit', 'Credited / returned — not replacing']];
function u10IssueSheet(id) { const rc = u10Rcvs().find((r) => r.id === id); if (!rc) return; const files = crList('cratt').filter((a) => !a.gone && a.rec === 'stk:' + rc.id);
  const probs = rc.lines.map((l, i) => ({ l, i })).filter((x) => x.l.prob);
  openSheet('⚠️ Order problem — ' + (rc.supName || 'delivery'), `<div class="hint">${rc.poNum ? 'PO ' + h(rc.poNum) + ' · ' : ''}${rc.invNo ? 'invoice ' + h(rc.invNo) + ' · ' : ''}received ${u10Date(rc.at)}${rc.by ? ' by ' + h(u10Who(rc.by)) : ''}${rc.issue === 'resolved' ? ' · ✓ sorted out ' + u10Date(rc.resAt) : ''}</div>
    ${files.length ? `<div class="f"><label>📎 Supplier's invoice</label>${files.map((a) => `<div>📎 <a href="#" data-act="att-open" data-id="${a.id}">${h(a.name)}</a></div>`).join('')}</div>` : ''}
    ${probs.map(({ l, i }) => { const p = crProd(l.prod); return `<div class="card" style="padding:8px;margin:6px 0"><b>${h(p ? p.name : '?')}</b> × ${l.bad} — ${h(u10ProbName(l.prob))}${l.batch ? ` <span class="hint">batch ${h(l.batch)}</span>` : ''}${l.res ? `<div class="hint">✓ ${h((U10_RES.find((r) => r[0] === l.res) || [])[1] || '')} ${l.resAt ? '— ' + u10Date(l.resAt) : ''}</div>` : `<div class="f"><label>What's happening with it?</label><select class="u10-res" data-i="${i}">${U10_RES.map(([k, t]) => `<option value="${k}">${h(t)}</option>`).join('')}</select></div>`}</div>`; }).join('')}
    <div class="f"><label>Comments</label>${(rc.comments || []).map((c) => `<div class="kv"><div class="k"><b>${h(u10Who(c.by) || '?')}</b><br><span class="hint">${u10Date(c.at)}</span></div><div class="v">${h(c.t).replace(/\n/g, '<br>')}</div></div>`).join('') || '<div class="hint">None yet.</div>'}</div>
    <div class="f"><label for="u10-cm">Add a comment</label><textarea id="u10-cm" rows="2"></textarea></div>`, async () => {
    const res = [...document.querySelectorAll('.u10-res')].map((s) => ({ i: +s.dataset.i, v: s.value })).filter((x) => x.v); const cm = ((document.getElementById('u10-cm') || {}).value || '').trim(); if (!res.length && !cm) return true;
    const nm = (l) => (crProd(l.prod) || {}).name || '?';
    if (!(await askBox('Save this?', `${res.map((x) => `<div>• ${h(nm(rc.lines[x.i]))}: ${h(U10_RES.find((r) => r[0] === x.v)[1])}</div>`).join('')}${cm ? `<p>Comment: ${h(cm)}</p>` : ''}`, 'Yes — save'))) return false;
    const o = rc.po && stkL('stkpo').find((x) => x.id === rc.po);
    res.forEach(({ i, v }) => { const l = rc.lines[i]; if (!l || l.res) return; l.res = v; l.resAt = Date.now(); l.resBy = u10Me();
      if (v === 'keep') stkAdd(l.prod, l.bad * (l.per || 1), 'office', l.batch, l.exp, 'Received after a problem was sorted — ' + (rc.poNum || rc.invNo || rc.supName || ''), rc.id);
      if (v === 'repl' && o && l.poi != null && o.lines[l.poi]) { const pl = o.lines[l.poi]; pl.got = crR4(Math.max(0, (+pl.got || 0) - l.bad)); pl.bo = { exp: '', at: Date.now(), note: 'replacement for ' + u10ProbName(l.prob).toLowerCase() }; }
      rc.comments.push({ at: Date.now(), by: u10Me(), t: `${nm(l)}: ${U10_RES.find((r) => r[0] === v)[1]}` }); });
    if (cm) rc.comments.push({ at: Date.now(), by: u10Me(), t: cm });
    if (rc.lines.every((l) => !l.prob || l.res)) { rc.issue = 'resolved'; rc.resAt = Date.now(); }
    touch(rc); if (o) u10PoStatus(o); stkSync(); setTimeout(renderAll, 0); toast(rc.issue === 'resolved' ? '✓ Sorted out' : 'Saved'); return true; }); if (SHEET) SHEET.snap = sheetState(); }

/* ---------- 🗑️ write-offs ---------- */
async function u10WriteOff(pid) { const id = pid || await stkPickProd(); if (!id) return; const p = crProd(id); const lots = stkLots(id).filter((x) => x.qty > 0).sort((a, b) => a.loc.localeCompare(b.loc) || (a.exp || '').localeCompare(b.exp || '')); if (!lots.length) { toast(`There's no ${p.name} in stock to write off`, 'warn'); return; }
  const ok = await askBox('🗑️ Write off — ' + p.name, `<div class="f"><label>Which one</label><select data-ask="lot" style="width:100%;padding:9px;font-size:16px">${lots.map((x) => `<option value="${x.id}">${h(stkLocName(x.loc))}${x.batch ? ' · batch ' + h(x.batch) : ''}${x.exp ? ' · expires ' + bkDate(x.exp, { day: 'numeric', month: 'short', year: 'numeric' }) : ''} · ${stkFmt(p, x.qty)}</option>`).join('')}</select></div>
    <div class="grid2"><div class="f"><label>How much${stkUnit(p) ? ' (' + h(p.unit) + ')' : ''}</label>${stkInp('q', '', 'number')}</div><div class="f"><label>Why</label><select data-ask="r" style="width:100%;padding:9px;font-size:16px">${u10Reasons().map((r) => `<option>${h(r)}</option>`).join('')}<option value="__other">Something else…</option></select></div></div>
    <div class="f"><label>Note</label>${stkInp('n', '')}</div><div class="hint">The reasons list is in Settings → Clinical records → 🗑️ Write-off reasons.</div>`, 'Write it off', true); if (!ok) return;
  const lot = stkL('stk').find((x) => x.id === ASK_FORM.lot); const q = +ASK_FORM.q || 0; if (!lot || !(q > 0)) { toast('Type how much'); return; } let r = ASK_FORM.r; const note = (ASK_FORM.n || '').trim(); if (r === '__other') { r = note || 'Other'; }
  const n = Math.min(q, +lot.qty || 0); lot.qty = crR4((+lot.qty || 0) - n); if (lot.qty <= 1e-6) lot.gone = true; touch(lot);
  stkLog({ prod: id, qty: -n, from: lot.loc, batch: lot.batch || '', exp: lot.exp || '', why: 'Written off — ' + r + (note && note !== r ? ' (' + note + ')' : ''), reason: r, note, kind: 'writeoff', lots: [{ batch: lot.batch, exp: lot.exp, qty: n }] });
  stkSync(); renderAll(); toast(`🗑️ Written off ${stkFmt(p, n)} ${p.name}${n < q ? ' (that was all of that batch)' : ''}`); }
function u10WriteOffsHtml() { const L = stkL('stkmv').filter((m) => m.kind === 'writeoff').sort((a, b) => b.at - a.at).slice(0, 60); if (!L.length) return ''; return `<details class="card"><summary><b>🗑️ Write-offs (${L.length}${L.length === 60 ? '+' : ''})</b></summary>${L.map((m) => { const p = crProd(m.prod); return `<div class="kv"><div class="k">${new Date(m.at).toLocaleDateString('en-AU', { day: 'numeric', month: 'short', year: 'numeric' })}</div><div class="v"><b>${h(p ? p.name : '?')}</b> ${stkFmt(p, -m.qty)} — ${h(m.reason || '')}${m.note && m.note !== m.reason ? ' · ' + h(m.note) : ''}<br><span class="hint">${h(stkLocName(m.from))}${m.batch ? ' · batch ' + h(m.batch) : ''}${m.by ? ' · ' + h(u10Who(m.by)) : ''}</span></div></div>`; }).join('')}</details>`; }

/* ---------- 📋 yearly stocktake and 💰 stock value (admin) ---------- */
const u10Admin = () => (typeof crAdmin === 'function' ? crAdmin() : true);
const u10Tracked = () => crList('crprod').filter((p) => !p.gone && stkTracked(p)).sort((a, b) => (u10CatName(u10Cat(a)) + a.name).localeCompare(u10CatName(u10Cat(b)) + b.name));
const u10CostOf = (p) => +(p.cost || p.supPrice || 0);
function u10TakeSheet() { if (!u10Admin()) { toast('Only the office can do the yearly stocktake', 'warn'); return; } const locs = stkLocs(); const P = u10Tracked();
  openSheet('📋 Yearly stocktake', `<div class="hint" style="margin-bottom:6px">The app's expected amount is shown in each box's label. Type what you count — leave a box empty if it matches. Then <b>Review the differences</b> before anything changes. <button type="button" class="btn small" data-act="u10-takecsv">⬇️ Count sheet (CSV)</button> <button type="button" class="btn small" data-act="u10-takepdf">🖨 Count sheet (PDF)</button></div>
    <div class="search" style="margin-bottom:6px"><input id="u10-tq" type="search" placeholder="Search" autocomplete="off" aria-label="Search the stocktake"></div>
    <div class="bk-dayscroll"><table class="ezy-t u10-take"><thead><tr><th>Item</th>${locs.map((l) => `<th>${h(stkLocName(l))}</th>`).join('')}</tr></thead><tbody>${P.map((p) => `<tr data-n="${h(p.name.toLowerCase())}"><td><b>${h(p.name)}</b><br><span class="hint">${h(u10CatName(u10Cat(p)))}${stkUnit(p) ? ' · ' + h(p.unit) : ''}</span></td>${locs.map((l) => `<td><label class="hint" style="display:block">expected ${+stkQty(p.id, l).toFixed(2)}</label><input class="u10-tc" type="number" step="any" data-p="${p.id}" data-l="${l}" style="width:80px" aria-label="${h(p.name)} counted at ${h(stkLocName(l))}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`, async () => {
    const V = [...document.querySelectorAll('.u10-tc')].filter((i) => i.value !== '').map((i) => { const p = crProd(i.dataset.p); const exp = stkQty(i.dataset.p, i.dataset.l); return { p, loc: i.dataset.l, exp, cnt: +i.value, diff: crR4(+i.value - exp) }; }); const D2 = V.filter((x) => Math.abs(x.diff) > 1e-6);
    if (!V.length) { toast('Type at least one count'); return false; } const val = crR2(D2.reduce((s, x) => s + x.diff * u10CostOf(x.p), 0));
    if (!(await askBox('📋 Review the differences', D2.length ? `<div style="max-height:50vh;overflow:auto"><table class="ezy-t"><tr><th>Item</th><th>Where</th><th>Expected</th><th>Counted</th><th>Difference</th><th>At cost</th></tr>${D2.map((x) => `<tr><td>${h(x.p.name)}</td><td>${h(stkLocName(x.loc))}</td><td>${+x.exp.toFixed(2)}</td><td>${x.cnt}</td><td style="color:${x.diff < 0 ? 'var(--red)' : 'inherit'}">${x.diff > 0 ? '+' : ''}${+x.diff.toFixed(2)}</td><td>${crMoney(x.diff * u10CostOf(x.p))}</td></tr>`).join('')}</table></div><p>Total difference at cost: <b>${crMoney(val)}</b> ex GST. ${V.length - D2.length} count${V.length - D2.length === 1 ? '' : 's'} matched.</p><p>Adjust the stock to the counts?</p>` : `<p>All ${V.length} counts match — nothing to adjust. Save the stocktake?</p>`, D2.length ? 'Yes — adjust the stock' : 'Yes — save it'))) return false;
    D2.forEach((x) => { if (x.diff > 0) stkAdd(x.p.id, x.diff, x.loc, '', '', 'Stocktake'); else stkTake(x.p.id, -x.diff, x.loc, 'Stocktake'); });
    const t = { id: uid('st'), at: Date.now(), by: u10Me(), lines: V.map((x) => ({ prod: x.p.id, loc: x.loc, exp: x.exp, cnt: x.cnt, diff: x.diff, cost: u10CostOf(x.p) })), value: val }; touch(t); stkL('stktake').push(t);
    stkSync(); setTimeout(renderAll, 0); toast(`📋 Stocktake saved — ${D2.length} adjusted`); return true; }); if (SHEET) SHEET.snap = sheetState(); }
document.addEventListener('input', (e) => { if (e.target.id !== 'u10-tq') return; const q = e.target.value.toLowerCase().trim(); document.querySelectorAll('.u10-take tbody tr').forEach((r) => { r.hidden = !!q && !(r.dataset.n || '').includes(q); }); });
function u10TakeRows() { const locs = stkLocs(); return [['Item', 'Category', 'Unit', ...locs.flatMap((l) => [stkLocName(l).replace(/^\S+\s/, '') + ' expected', stkLocName(l).replace(/^\S+\s/, '') + ' counted'])], ...u10Tracked().map((p) => [p.name, u10CatName(u10Cat(p)), stkUnit(p), ...locs.flatMap((l) => [+stkQty(p.id, l).toFixed(2), ''])])]; }
function u10ValueRows() { const P = u10Tracked().map((p) => { const q = stkQty(p.id); return { p, q, c: u10CostOf(p), v: crR2(q * u10CostOf(p)) }; }).filter((x) => x.q); const g = {}; P.forEach((x) => { const k = u10CatName(u10Cat(x.p)); (g[k] = g[k] || []).push(x); }); return { P, g, tot: crR2(P.reduce((s, x) => s + x.v, 0)) }; }
function u10ValueSheet() { if (!u10Admin()) { toast('Only the office can see the stock value', 'warn'); return; } const V = u10ValueRows();
  openSheet('💰 Stock value', `<div class="hint" style="margin-bottom:6px">Everything in stock (office and vehicles) × its cost price, ex GST — for the accounts. <button type="button" class="btn small" data-act="u10-valcsv">⬇️ Excel (CSV)</button> <button type="button" class="btn small" data-act="u10-valpdf">🖨 PDF</button></div>
    <div class="card"><div class="kv"><div class="v"><b>Total stock value</b></div><b>${crMoney(V.tot)}</b></div>${Object.entries(V.g).map(([k, L]) => `<div class="kv"><div class="v">${h(k)} <span class="hint">(${L.length})</span></div><span>${crMoney(L.reduce((s, x) => s + x.v, 0))}</span></div>`).join('')}</div>
    ${Object.entries(V.g).map(([k, L]) => `<details class="card"><summary><b>${h(k)}</b> — ${crMoney(L.reduce((s, x) => s + x.v, 0))}</summary><table class="ezy-t"><tr><th>Item</th><th>On hand</th><th>Cost</th><th>Value</th></tr>${L.map((x) => `<tr><td>${h(x.p.name)}</td><td>${stkFmt(x.p, x.q)}</td><td>${crMoney(x.c)}</td><td>${crMoney(x.v)}</td></tr>`).join('')}</table></details>`).join('') || '<div class="hint">Nothing in stock yet.</div>'}`, () => true);
  const sv = document.getElementById('sheet-save'); if (sv) sv.textContent = 'Close'; }
document.addEventListener('click', (e) => { const el = e.target.closest && e.target.closest('[data-act^=u10-take],[data-act^=u10-val]'); if (!el) return; const a = el.dataset.act; e.preventDefault(); e.stopPropagation(); const day = bkToday();
  if (a === 'u10-takesheet') return u10TakeSheet(); if (a === 'u10-value') return u10ValueSheet();
  if (a === 'u10-takecsv') return u10Csv(`Stocktake count sheet ${day}.csv`, u10TakeRows());
  if (a === 'u10-takepdf') { const R = u10TakeRows(); return u10Print('Stocktake count sheet', `<table><tr>${R[0].map((c) => `<th>${h(c)}</th>`).join('')}</tr>${R.slice(1).map((r) => `<tr>${r.map((c, i) => `<td class="${i > 2 ? 'n' : ''}">${h(c)}</td>`).join('')}</tr>`).join('')}</table>`); }
  if (a === 'u10-valcsv') { const V = u10ValueRows(); return u10Csv(`Stock value ${day}.csv`, [['Category', 'Item', 'On hand', 'Unit', 'Cost ex GST', 'Value ex GST'], ...V.P.map((x) => [u10CatName(u10Cat(x.p)), x.p.name, +x.q.toFixed(2), stkUnit(x.p), x.c, x.v]), ['', 'Total', '', '', '', V.tot]]); }
  if (a === 'u10-valpdf') { const V = u10ValueRows(); return u10Print('Stock value', `<p><b>Total: ${crMoney(V.tot)}</b> ex GST</p>${Object.entries(V.g).map(([k, L]) => `<h2>${h(k)} — ${crMoney(L.reduce((s, x) => s + x.v, 0))}</h2><table><tr><th>Item</th><th class="n">On hand</th><th class="n">Cost</th><th class="n">Value</th></tr>${L.map((x) => `<tr><td>${h(x.p.name)}</td><td class="n">${stkFmt(x.p, x.q)}</td><td class="n">${crMoney(x.c)}</td><td class="n">${crMoney(x.v)}</td></tr>`).join('')}</table>`).join('')}`); } }, true);

/* ---------- the Stock and Orders pages ---------- */
function u10TodoHtml() { const I = u10OpenIssues(); const P = u10PriceIssues(); if (!I.length && !P.length) return '';
  return `<div class="card u10-todo"><h3>⚠️ To sort out</h3>${I.map((r) => { const n = r.lines.filter((l) => l.prob && !l.res); return `<div class="kv bk-tap" data-act="u10-issue" data-id="${r.id}" style="align-items:center"><div class="v"><b>📦 ${h(r.supName || 'Delivery')}</b>${r.poNum ? ' — PO ' + h(r.poNum) : ''} <span class="hint">${new Date(r.at).toLocaleDateString('en-AU')}</span><br><span class="hint">${n.map((l) => `${h((crProd(l.prod) || {}).name || '?')} × ${l.bad} ${h(u10ProbName(l.prob).toLowerCase())}`).join(' · ')}</span></div><span class="btn small">Sort it out</span></div>`; }).join('')}
    ${P.length ? `<details${I.length ? '' : ' open'}><summary><b>💲 ${P.length} item${P.length === 1 ? '' : 's'} with a price that doesn't look right</b></summary>${P.slice(0, 60).map((x) => `<div class="kv" style="align-items:center;flex-wrap:wrap"><div class="v" style="flex:1"><b>${h(x.p.name)}</b><br><span class="hint">${x.why.join(' · ')}</span></div><button class="btn small" data-act="cr-prodedit" data-id="${x.p.id}">✏️ Fix it</button><button class="btn small" data-act="u10-priceok" data-id="${x.p.id}">✓ It's meant to be</button></div>`).join('')}</details>` : ''}</div>`; }
function u10RcvListHtml() { const L = u10Rcvs().sort((a, b) => b.at - a.at).slice(0, 30); if (!L.length) return ''; return `<details class="card"><summary><b>📥 Deliveries received (${L.length}${L.length === 30 ? '+' : ''})</b></summary>${L.map((r) => { const nf = crList('cratt').filter((a) => !a.gone && a.rec === 'stk:' + r.id); return `<div class="kv bk-tap" data-act="u10-issue" data-id="${r.id}"><div class="k">${new Date(r.at).toLocaleDateString('en-AU', { day: 'numeric', month: 'short' })}</div><div class="v"><b>${h(r.supName || 'Delivery')}</b>${r.poNum ? ' — PO ' + h(r.poNum) : ''}${r.invNo ? ' · invoice ' + h(r.invNo) : ''} ${r.issue === 'open' ? '<span class="pill" style="font-size:11px">⚠️ problem</span>' : r.issue === 'resolved' ? '<span class="pill" style="font-size:11px">✓ sorted</span>' : ''}<br><span class="hint">${r.lines.length} item${r.lines.length === 1 ? '' : 's'}${nf.length ? ' · 📎 ' + nf.length : ' · no invoice attached'}${r.by ? ' · ' + h(u10Who(r.by)) : ''}</span></div></div>`; }).join('')}</details>`; }
if (typeof stkStockHtml === 'function') stkStockHtml = (function (orig) { return function () { let html = orig.apply(this, arguments); if (STK.sel) return html;
  html = html.replace('<button class="btn small primary" data-act="stk-in">➕ Stock in (no order)</button>', `<button class="btn small primary" data-act="u10-rcv">📥 Receive a delivery</button><button class="btn small" data-act="stk-in">➕ Stock in (no order)</button><button class="btn small" data-act="u10-wo">🗑️ Write off</button>${u10Admin() ? '<button class="btn small" data-act="u10-takesheet">📋 Yearly stocktake</button><button class="btn small" data-act="u10-value">💰 Stock value</button>' : ''}`);
  return u10TodoHtml() + html; }; })(stkStockHtml);
if (typeof stkProdHtml === 'function') stkProdHtml = (function (orig) { return function (id) { let html = orig.apply(this, arguments); const p = crProd(id); if (!p) return html; const B = u10Breaks(p);
  html = html.replace(/(<button class="btn small" data-act="stk-count" data-id="[^"]+">📝 Count<\/button>)/, `$1<button class="btn small" data-act="u10-wo" data-id="${p.id}">🗑️ Write off</button><button class="btn small" data-act="u10-breaks" data-id="${p.id}">💲 Price breaks${B.length ? ' (' + B.length + ')' : ''}</button>`);
  return B.length ? html.replace('<div class="card"><h3>History</h3>', `<div class="card"><h3>💲 Price breaks</h3>${B.map((b) => `<div class="kv"><div class="v">${b.sup ? h(b.sup) + ': ' : ''}${b.qty}+ at ${crMoney(b.price)} each</div></div>`).join('')}</div><div class="card"><h3>History</h3>`) : html; }; })(stkProdHtml);
if (typeof stkOrdersHtml === 'function') stkOrdersHtml = (function (orig) { return function () { let html = orig.apply(this, arguments);
  html = html.replace(/<span class="pill" style="font-size:11px">issue<\/span>/g, '<span class="pill" style="font-size:11px">⚠️ Problem to sort out</span>').replace('<button class="btn small" data-act="stk-ponew">➕ New order</button>', '<button class="btn small" data-act="stk-ponew">➕ New order</button><button class="btn small" data-act="u10-rcv">📥 Receive a delivery (no order)</button>');
  return u10TodoHtml() + html + u10RcvListHtml(); }; })(stkOrdersHtml);
if (typeof stkPoHtml === 'function') stkPoHtml = (function (orig) { return function (id) { const o = stkL('stkpo').find((x) => x.id === id && !x.gone); let html = orig.apply(this, arguments); if (!o) return html; const R = u10Rcvs().filter((r) => r.po === o.id).sort((a, b) => a.at - b.at);
  if (o.status === 'issue') html = html.replace(/<div class="hint">Received/, '<div class="hint">⚠️ Received — with a problem to sort out');
  html = html.replace('<div class="actions"><button class="btn primary" data-act="stk-posend"', u10PoBreaksHtml(o) + '<div class="actions"><button class="btn primary" data-act="stk-posend"');
  if (R.length) html += `<div class="card"><h3>📥 Deliveries for this order</h3>${R.map((r) => `<div class="kv bk-tap" data-act="u10-issue" data-id="${r.id}"><div class="k">${new Date(r.at).toLocaleDateString('en-AU', { day: 'numeric', month: 'short' })}</div><div class="v">${r.invNo ? 'Invoice ' + h(r.invNo) : 'Delivery'} — ${r.lines.map((l) => `${h((crProd(l.prod) || {}).name || '?')} × ${l.qty}`).join(', ')}${r.issue === 'open' ? ' <span class="pill" style="font-size:11px">⚠️ problem</span>' : ''}</div></div>`).join('')}</div>`;
  return html; }; })(stkPoHtml);
if (typeof stkHistHtml === 'function') stkHistHtml = (function (orig) { return function () { return u10WriteOffsHtml() + orig.apply(this, arguments); }; })(stkHistHtml);
document.addEventListener('click', async (e) => { const el = e.target.closest && e.target.closest('[data-act=u10-rcv],[data-act=u10-wo],[data-act=u10-breaks],[data-act=u10-issue],[data-act=u10-priceok]'); if (!el) return; e.preventDefault(); e.stopPropagation(); const a = el.dataset.act;
  if (a === 'u10-rcv') return u10Receive(null); if (a === 'u10-wo') return u10WriteOff(el.dataset.id); if (a === 'u10-breaks') return u10BreaksSheet(el.dataset.id); if (a === 'u10-issue') return u10IssueSheet(el.dataset.id);
  if (a === 'u10-priceok') { const x = u10PriceIssues().find((y) => y.p.id === el.dataset.id); if (!x || !(await ask(`${x.p.name}: ${x.why.join('; ').replace(/<[^>]+>/g, '')}.\n\nMark this price as meant to be? (It comes back if the price changes again.)`, 'Yes — it\'s meant to be'))) return; x.p.priceOk = x.key; touch(x.p); stkSync(); renderAll(); } }, true);

/* ---------- Settings → Clinical records: expiry months, write-off reasons, mark-up bands ---------- */
function u10SetCard() { const R = u10Reasons(); const B = u10Bands(); const cats = (typeof stk2Cats === 'function' ? stk2Cats() : []);
  const band = (cat, b) => `<div class="u10-band" data-cat="${h(cat)}" style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin:3px 0"><span class="hint">cost from $</span><input class="u10-bf" type="number" min="0" step="0.01" value="${b[0] ?? ''}" style="width:80px" aria-label="Cost from"><span class="hint">to under $</span><input class="u10-bt" type="number" min="0" step="0.01" value="${b[1] ?? ''}" style="width:80px" aria-label="Cost to (empty for no limit)"><span class="hint">→</span><input class="u10-bp2" type="number" min="0" step="0.1" value="${b[2] ?? ''}" style="width:70px" aria-label="Mark-up %"><span class="hint">%</span><button type="button" class="btn small" data-act="u10-sbdel" aria-label="Delete this band">🗑️</button></div>`;
  return `<div class="card"><h3>📦 Stock and ordering</h3><div class="u10-set">
    <div class="f"><label for="u10-months">Flag deliveries with less than this many months to expiry</label><input id="u10-months" type="number" min="1" step="1" value="${u10Months()}" style="width:90px"></div>
    <div class="f"><label>🗑️ Write-off reasons <span class="hint">(↑ ↓ or drag to reorder)</span></label><div data-dnd="u10rs">${R.map((r) => `<div class="dragrow u10-rrow" style="display:flex;gap:6px;align-items:center;margin:3px 0"><span class="draghandle" aria-hidden="true">⠿</span><button type="button" class="btn small" data-act="u10-rmv" data-d="-1" aria-label="Up">↑</button><button type="button" class="btn small" data-act="u10-rmv" data-d="1" aria-label="Down">↓</button><input class="u10-rn" value="${h(r)}" style="flex:1" aria-label="Reason"><button type="button" class="btn small" data-act="u10-rdel" aria-label="Delete this reason">🗑️</button></div>`).join('')}</div><button type="button" class="btn small" data-act="u10-radd">➕ Add a reason</button></div>
    <div class="f"><label>💡 Suggested mark-up bands <span class="hint">— a guide shown on each price list item (by its cost a bottle / box). Mark-up is still set on each item.</span></label>
      <div id="u10-bands">${Object.entries(B).map(([cat, L]) => `<div class="u10-bcat card" data-cat="${h(cat)}" style="padding:8px;margin:6px 0"><b>${h(u10CatName(cat))}</b> <button type="button" class="btn small" data-act="u10-sbcdel" aria-label="Delete this category's bands">🗑️</button><div class="u10-bl">${L.map((b) => band(cat, b)).join('')}</div><button type="button" class="btn small" data-act="u10-sbadd">➕ Add a band</button></div>`).join('')}</div>
      <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><select id="u10-bnew" aria-label="Category">${cats.filter((c) => !B[c.id]).map((c) => `<option value="${h(c.id)}">${h(c.name)}</option>`).join('')}</select><button type="button" class="btn small" data-act="u10-sbcadd">➕ Bands for this category</button></div>
      <template id="u10-bandtpl">${band('', ['', '', ''])}</template></div>
    <div class="actions"><button class="btn small primary" data-act="u10-ssave">Save</button><button class="btn small" data-act="u10-sreset">↺ Standard bands and reasons</button></div></div></div>`; }
if (typeof crSettingsHtml === 'function') crSettingsHtml = (function (orig) { return function () { const html = orig.apply(this, arguments); const w = '<div class="cr-setwrap" data-tab="records">'; return html.includes(w) ? html.replace(w, w + u10SetCard()) : html + u10SetCard(); }; })(crSettingsHtml);
document.addEventListener('click', async (e) => { const el = e.target.closest && e.target.closest('[data-act^=u10-r],[data-act^=u10-sb],[data-act=u10-ssave],[data-act=u10-sreset]'); if (!el || el.dataset.act === 'u10-rcv' || el.dataset.act === 'u10-rldel' || el.dataset.act === 'u10-rladd') return; const a = el.dataset.act; e.preventDefault(); e.stopPropagation(); const card = el.closest('.u10-set'); if (!card) return;
  if (a === 'u10-rmv') { const r = el.closest('.u10-rrow'); if (+el.dataset.d < 0 && r.previousElementSibling) r.parentNode.insertBefore(r, r.previousElementSibling); if (+el.dataset.d > 0 && r.nextElementSibling) r.parentNode.insertBefore(r.nextElementSibling, r); return; }
  if (a === 'u10-rdel') { el.closest('.u10-rrow').remove(); return; }
  if (a === 'u10-radd') { const box = card.querySelector('[data-dnd=u10rs]'); box.insertAdjacentHTML('beforeend', `<div class="dragrow u10-rrow" style="display:flex;gap:6px;align-items:center;margin:3px 0"><span class="draghandle" aria-hidden="true">⠿</span><button type="button" class="btn small" data-act="u10-rmv" data-d="-1" aria-label="Up">↑</button><button type="button" class="btn small" data-act="u10-rmv" data-d="1" aria-label="Down">↓</button><input class="u10-rn" style="flex:1" aria-label="Reason"><button type="button" class="btn small" data-act="u10-rdel" aria-label="Delete this reason">🗑️</button></div>`); box.lastElementChild.querySelector('input').focus(); return; }
  if (a === 'u10-sbdel') { el.closest('.u10-band').remove(); return; }
  if (a === 'u10-sbcdel') { el.closest('.u10-bcat').remove(); return; }
  if (a === 'u10-sbadd') { const c = el.closest('.u10-bcat'); c.querySelector('.u10-bl').insertAdjacentHTML('beforeend', card.querySelector('#u10-bandtpl').innerHTML.replace('data-cat=""', `data-cat="${h(c.dataset.cat)}"`)); return; }
  if (a === 'u10-sbcadd') { const s = card.querySelector('#u10-bnew'); if (!s || !s.value) return; const id = s.value; card.querySelector('#u10-bands').insertAdjacentHTML('beforeend', `<div class="u10-bcat card" data-cat="${h(id)}" style="padding:8px;margin:6px 0"><b>${h(u10CatName(id))}</b> <button type="button" class="btn small" data-act="u10-sbcdel" aria-label="Delete this category's bands">🗑️</button><div class="u10-bl">${card.querySelector('#u10-bandtpl').innerHTML.replace('data-cat=""', `data-cat="${h(id)}"`)}</div><button type="button" class="btn small" data-act="u10-sbadd">➕ Add a band</button></div>`); s.querySelector(`option[value="${id}"]`).remove(); return; }
  if (a === 'u10-sreset') { if (!(await ask('Put the mark-up bands and write-off reasons back to the standard ones?', 'Yes — standard'))) return; delete u10S().mkBands; delete u10S().adjReasons; touch(D.settings); S.skipConfirm = true; await changed(); toast('Back to the standard ones'); return; }
  if (a === 'u10-ssave') { const months = Math.max(1, Math.round(+card.querySelector('#u10-months').value || 6)); const R = [...card.querySelectorAll('.u10-rn')].map((i) => i.value.trim()).filter(Boolean); const B = {}; card.querySelectorAll('.u10-bcat').forEach((c) => { const L = [...c.querySelectorAll('.u10-band')].map((b) => [b.querySelector('.u10-bf').value === '' ? 0 : +b.querySelector('.u10-bf').value, b.querySelector('.u10-bt').value === '' ? '' : +b.querySelector('.u10-bt').value, +b.querySelector('.u10-bp2').value]).filter((b) => b[2] > 0 || b[2] === 0).sort((x, y) => x[0] - y[0]); if (L.length) B[c.dataset.cat] = L; });
    if (!R.length) { toast('Keep at least one write-off reason'); return; } if (!(await ask(`Save the stock settings?\n\n• ${months} months to expiry\n• Write-off reasons: ${R.join(', ')}\n• Mark-up bands for ${Object.keys(B).map(u10CatName).join(', ') || 'no categories'}`, 'Yes — save'))) return;
    u10S().stkExpMonths = months; u10S().adjReasons = R; u10S().mkBands = B; NEXT_LOG_LABEL = 'Stock settings changed'; touch(D.settings); S.skipConfirm = true; await changed(); toast('Saved'); } }, true);

/* ---------- admin check jobs ---------- */
const U10_CHECKS = [
  ['chk247-po', 'Check: 📧 purchase orders by email', 'Records → Stock → Orders → ➕ New order: choose items, then 📧 Send — it asks before sending to the supplier. The order shows Draft → Sent → Part received → Received (or ⚠️ Problem to sort out).', 'stk:orders'],
  ['chk247-recv', 'Check: 📥 receive a delivery with its invoice', 'Records → Stock → 📥 Receive a delivery (or 📥 It\'s arrived on a sent order): drag the supplier\'s invoice in, type how many came, batch and expiry. Stock only goes up by what came.', 'stk:stock'],
  ['chk247-cost', 'Check: cost price changes on receiving', 'Receive an item at a higher cost than before — "Update the cost price" is ticked. At a lower cost it shows the drop but isn\'t ticked. Ticked ones change the cost (and the sale price when it\'s set by mark-up).', 'stk:orders'],
  ['chk247-breaks', 'Check: 💲 supplier price breaks', 'Open an item in Records → Stock → 💲 Price breaks: add "from 24 at $x each". On a draft order for that supplier, the price follows the quantity and "Make it 24" suggests the better quantity.', 'stk:stock'],
  ['chk247-expiry', 'Check: ⚠ short-dated deliveries', 'When receiving, type an expiry under 6 months away — it\'s flagged. The number of months is in Settings → Clinical records → 📦 Stock and ordering.', 'setrec'],
  ['chk247-problem', 'Check: ⚠️ order problems', 'Receive a delivery and set "Any problem?" to Broken with a note. The problem items aren\'t put in stock; "⚠️ To sort out" shows at the top of Stock until you choose Keep it / Replacement coming / Credited, with comments kept.', 'stk:stock'],
  ['chk247-reorder', 'Check: reorder to the maximum', 'Records → Stock → Orders: items at or below their minimum show with "order up to the maximum". A draft below a supplier\'s minimum order warns and suggests other items from that supplier. (Supplier rules are on the Suppliers tab.)', 'stk:orders'],
  ['chk247-writeoff', 'Check: 🗑️ write-offs', 'Records → Stock → 🗑️ Write off: choose the item and batch, how much and why (Expired / Broken / Wasted). It shows under History → 🗑️ Write-offs with who did it. The reasons list is in Settings → Clinical records.', 'stk:stock'],
  ['chk247-stocktake', 'Check: 📋 yearly stocktake', 'Records → Stock → 📋 Yearly stocktake (office only): print or download the count sheet, type a few counts, Review the differences, then adjust. It\'s logged as "Stocktake".', 'stk:stock'],
  ['chk247-value', 'Check: 💰 stock value', 'Records → Stock → 💰 Stock value (office only): the total at cost by category, with ⬇️ Excel (CSV) and 🖨 PDF.', 'stk:stock'],
  ['chk247-markup', 'Check: 💡 suggested mark-up', 'Open a price list item (an S4 medication with a cost) — under the mark-up it suggests the band\'s % with a "Use" button. The bands are in Settings → Clinical records → 📦 Stock and ordering.', 'prods'],
  ['chk247-pricing', 'Check: 💲 pricing check', 'Records → Stock: "⚠️ To sort out" lists any item sold below cost, with a negative price, or below cost once a discount rule applies — ✏️ Fix it, or ✓ It\'s meant to be.', 'stk:stock']];
if (typeof u8Go === 'function') u8Go = (function (orig) { return function (k) { if (typeof k === 'string' && k.startsWith('stk:')) { if (typeof SHEET !== 'undefined' && SHEET) closeSheet(); S.tab = 'rec'; CR.page = 'stock'; STK.tab = k.slice(4); STK.sel = null; STK.po = null; S.sel = null; document.body.classList.remove('show-detail'); renderAll(); window.scrollTo(0, 0); return; } return orig.apply(this, arguments); }; })(u8Go);
if (typeof SETUP !== 'undefined' && typeof U8_TRY !== 'undefined') U10_CHECKS.forEach(([id, t, tryIt, go]) => { U8_TRY[id] = tryIt; U8_TO[id] = go; if (SETUP.some((x) => x.id === id)) return; SETUP.push({ id, t, steps: [tryIt, `<button type="button" class="btn small" data-act="u8-go" data-go="${go}">➡️ Take me there</button>`, 'If it does what you want, tick <b>✓ Done</b>. If not, tell Claude what\'s wrong.'] }); });
window.u10PriceIssues = u10PriceIssues; window.u10Suggest = u10Suggest; window.u10Tier = u10Tier; window.u10Receive = u10Receive; window.u10WriteOff = u10WriteOff; window.u10CostUpdate = u10CostUpdate;
document.addEventListener('keydown', (e) => { if (e.target.id === 'u10-add' && e.key === 'Enter') { e.preventDefault(); const b = document.querySelector('[data-act=u10-rladd]'); if (b) b.click(); } });
